      {q:"Цель расследования —",options:["Установить обстоятельства и причины и предупредить повторение","Найти виновного любой ценой","Скрыть недостатки","Остановить обучение"]},
      {q:"В описании происшествия следует",options:["Отделять подтверждённые факты от предположений","Добавлять догадки как факты","Изменять время события","Не указывать оборудование"]},
      {q:"Культура безопасности включает",options:["Сообщение об опасностях и готовность остановить небезопасную работу","Сокрытие ошибок","Обход защитных устройств","Работу любой ценой"]}
